module fixed_point_adder(
    input [N-1:0] a, 
    input [N-1:0] b, 
    output [N-1:0] c
);
    parameter Q = 4;
    parameter N = 8;
    reg [N-1:0] res;
    assign c = (a[N-1] == b[N-1]) ? res : (~res + 1);
    always @(a or b) begin
        if(a[N-1]==b[N-1])
            res = (a[N-2:0]+b[N-2:0]);
        else if(a[N-1]>b[N-1]) begin
            res = (a[N-2:0]-b[N-2:0]);
            res[N-1]=1'd0;
        end
        else if(b[N-1]>a[N-1]) begin
            res = (b[N-2:0]-a[N-2:0]);
            res[N-1]=(res==0)?1'd0:(~(res)+1);
        end
    end

endmodule
